import{_ as i,a0 as s,w as r,s as a,ao as l,I as p,x as n,a1 as o,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Ubuntu vs. openSUSE：不同的公司控制风格的比较 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu vs. openSUSE：不同的公司控制风格的比较 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu vs. openSUSE：不同的公司控制风格的比较 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu vs. openSUSE：不同的公司控制风格的比较 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Ubuntu vs. openSUSE--Weighing different styles of corporate control","title":"Ubuntu vs. openSUSE：不同的公司控制风格的比较","tag":"201311","desc":""},"relativePath":"201311/Ubuntu vs. openSUSE--Weighing different styles of corporate control.md","filePath":"[post].md"}'),S={name:"201311/Ubuntu vs. openSUSE--Weighing different styles of corporate control.md"};function U(d,t,f,m,x,b){const e=s("Link");return r(),a("div",null,[t[11]||(t[11]=l('<h1 id="ubuntu-vs-opensuse-不同的公司控制风格的比较" tabindex="-1">Ubuntu vs. openSUSE：不同的公司控制风格的比较 <a class="header-anchor" href="#ubuntu-vs-opensuse-不同的公司控制风格的比较" aria-label="Permalink to “Ubuntu vs. openSUSE：不同的公司控制风格的比较”">​</a></h1><p><em>Ubuntu和OpenSUSE以不同的方式发展他们的Linux发行版。你觉得哪种好？</em></p><p>相当多的linux开发都接受来自那些有意改善Linux的公司的资助，这早已不是秘密（这里的Linux我指的是组成一个完整Linux系统的任何部分）。但是，许多公司进行资助的方式却有很大不同。</p><p>让我们看看两个很典型的例子：Ubuntu和openSUSE。</p><p>这两者都是Linux发行版。两者都是一个规模庞大、长期持续且非常成功的项目，并且它们都有一个包括志愿者和付费职员的大型社区。然而，两者之间的不同还是相当明显而且非常重要。</p><p>对于Ubuntu，它发展的主要方向是由Canonical的团队及其领袖Mark Shuttleworth决定的。当谈到Canonical真正“掌舵”Ubuntu时，我们能很快就会想起两个例子，例如Unity（Ubuntu自己的用户界面）和Mir（Ubuntu自己的显示服务）。在许多事情上，母公司都会在没有协商（可以这么说）的情况下设定目标、项目和优先级。例如，Ubuntu的Unity用户界面对于Canonical公司广泛战略目标来说是必须的。一些社区成员喜欢它，另一些则讨厌它。但是不管怎么说，Unity都已经成为Ubuntu的默认用户界面了。</p><p>但是这是一件坏事吗？我不确信它到底是好还是坏。这只是这个项目如何与公司相处的问题。</p><p>于此形成对比的是openSUSE，它也有一个公司掌控者，好吧，就是SUSE。关键的不同点是SUSE以“SUSE Linux企业版”的形式提供一个商业发行版。尽管openSUSE（社区Linux发行版）与SUSE Linux发行版（商业发行版）在技术上有许多重叠之处...然而专业的说，两者是不同的。</p><p>这意味着SUSE，作为一个公司，对待openSUSE时可以更多的采取放手不管的方式，他们的兴趣就是寻找那些被改善的关键性技术（例如，Btrfs文件系统），检测以及打包社区发行版中那些他们想包含在商业发行版中的软件包，但是社区发行版与商业发行版分离的方式与Canonical采取方式相比，给他们提供了更大的灵活性。在这方面，和Canonical不同。</p><p>这种方法和红帽对待Fedora的方式非常相似，已经成为了一个公司使用社区Linux发行版为基础，销售企业级的Linux系统的一种成功之路。</p><p>不过，坦白的说两种模式我都看到了优点和缺点。在组织上以及管理上（公众部分）他们都面临着各自的难题。实际上，这两种方法与它们的不同点比起来，相同点更多一些。</p><p>我非常愿意听到你们对此的看法。你是更喜欢你的以社区为基础的Linux发行版有一个单一的领袖？还是更喜欢你Linux发行版的大多数决定都是有社区驱动的呢？公司是否应该强势控制Linux发行版，还是应该大胆放手让社区来决定呢？请在评论里留言，让我们知道你的看法。</p><hr>',13)),p("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://www.networkworld.com/community/node/84250"},{default:u(()=>[...t[0]||(t[0]=[n("http://www.networkworld.com/community/node/84250",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=n("译者：",-1)),o(e,{href:"https://github.com/Linux-pdz"},{default:u(()=>[...t[2]||(t[2]=[n("Linux-pdz",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:u(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const C=i(S,[["render",U]]);export{T as __pageData,C as default};
